{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2185-05-01 01:15:00",
      "speaker": "Doctor",
      "text": "Hi, I’m Dr. Lee, one of your hospital doctors. You came in from your clinic visit because of nausea, vomiting, and weight loss. Can you tell me more about what’s been going on?"
    },
    {
      "turn_number": 2,
      "time": "2185-05-01 01:18:00",
      "speaker": "Patient",
      "text": "Yes… I’ve been so sick. The pain in my belly is constant—especially in the upper parts and around my G-tube. I’ve lost 32 pounds since I stopped TPN. I can’t keep anything down."
    },
    {
      "turn_number": 3,
      "time": "2185-05-01 01:21:00",
      "speaker": "Doctor",
      "text": "I see. And your G-tube isn’t draining much anymore—only about 300 cc a day. That’s less than before. We think it might not be working as well. We’re going to replace it today to help with the venting."
    },
    {
      "turn_number": 4,
      "time": "2185-05-01 01:24:00",
      "speaker": "Patient",
      "text": "Oh… will that hurt? I’m already in pain even with my morphine every six hours."
    },
    {
      "turn_number": 5,
      "time": "2185-05-01 01:26:00",
      "speaker": "Doctor",
      "text": "We’ll give you some extra medication to keep you comfortable during the procedure. It’s done with imaging guidance, and we expect it to help reduce your nausea and bloating."
    },
    {
      "turn_number": 6,
      "time": "2185-05-01 12:30:00",
      "speaker": "Doctor",
      "text": "The G-tube was successfully replaced. We put in a shorter one with extra side holes, and it’s positioned well in your stomach. We hope this improves drainage."
    },
    {
      "turn_number": 7,
      "time": "2185-05-01 12:33:00",
      "speaker": "Patient",
      "text": "That’s good. But I’m still nauseated. And I feel weak. I haven’t eaten in weeks."
    },
    {
      "turn_number": 8,
      "time": "2185-05-01 12:36:00",
      "speaker": "Doctor",
      "text": "We know. Your labs show low calcium and you’re malnourished. We’re working on getting you back on TPN, but we need insurance approval first. In the meantime, we’re giving IV fluids and supplements."
    },
    {
      "turn_number": 9,
      "time": "2185-05-02 08:45:00",
      "speaker": "Patient",
      "text": "Doctor, I’m still nauseous. The promethazine helps a little, but not enough. Can we try something else?"
    },
    {
      "turn_number": 10,
      "time": "2185-05-02 08:48:00",
      "speaker": "Doctor",
      "text": "Yes, we’re adding ondansetron and ativan for nausea. We’re also continuing octreotide, which helps slow gut motility. We’ll monitor how you respond."
    },
    {
      "turn_number": 11,
      "time": "2185-05-03 09:00:00",
      "speaker": "Doctor",
      "text": "Your stool test came back negative for C. diff, so we don’t think it’s an infection causing the nausea. That’s good news."
    },
    {
      "turn_number": 12,
      "time": "2185-05-03 09:03:00",
      "speaker": "Patient",
      "text": "I’m glad. But my G-tube output is still low. Is that normal after the change?"
    },
    {
      "turn_number": 13,
      "time": "2185-05-03 09:06:00",
      "speaker": "Doctor",
      "text": "It’s lower than we’d like. We’re concerned there might be a partial blockage at the stomach outlet. We’re discussing with GI whether we need to switch the tube type again."
    },
    {
      "turn_number": 14,
      "time": "2185-05-04 10:15:00",
      "speaker": "Doctor",
      "text": "We’re going to change your G-tube again—this time to a Wills-Ogelsby tube. It’s designed to work better if there’s a blockage. We’ll do it early this week."
    },
    {
      "turn_number": 15,
      "time": "2185-05-04 10:18:00",
      "speaker": "Patient",
      "text": "Another procedure? How soon?"
    },
    {
      "turn_number": 16,
      "time": "2185-05-04 10:20:00",
      "speaker": "Doctor",
      "text": "We’ll schedule it for tomorrow. We want to make sure your stomach can drain properly so you feel less full and nauseated."
    },
    {
      "turn_number": 17,
      "time": "2185-05-05 13:00:00",
      "speaker": "Doctor",
      "text": "The new Wills-Ogelsby tube is in. Output has already improved—now over 500 cc/day. That’s a good sign."
    },
    {
      "turn_number": 18,
      "time": "2185-05-05 13:03:00",
      "speaker": "Patient",
      "text": "I do feel a bit better. Less bloated. But I’m still tired and weak."
    },
    {
      "turn_number": 19,
      "time": "2185-05-05 13:06:00",
      "speaker": "Doctor",
      "text": "That’s expected. You’ve been malnourished. We’ve gotten approval for TPN. We’ll place a central line so you can receive it at home."
    },
    {
      "turn_number": 20,
      "time": "2185-05-06 09:30:00",
      "speaker": "Patient",
      "text": "What kind of line? I’ve had port-a-caths before."
    },
    {
      "turn_number": 21,
      "time": "2185-05-06 09:33:00",
      "speaker": "Doctor",
      "text": "This will be a tunneled femoral line in your left groin. It’s safer for now, given your history of clots and abdominal surgeries."
    },
    {
      "turn_number": 22,
      "time": "2185-05-07 10:00:00",
      "speaker": "Doctor",
      "text": "We’re also checking your blood cultures to make sure there’s no infection. We’ll repeat them tomorrow."
    },
    {
      "turn_number": 23,
      "time": "2185-05-08 09:30:00",
      "speaker": "Doctor",
      "text": "Good news—both blood cultures are negative. No sign of infection in your bloodstream."
    },
    {
      "turn_number": 24,
      "time": "2185-05-08 09:33:00",
      "speaker": "Patient",
      "text": "That’s a relief. When will I start TPN?"
    },
    {
      "turn_number": 25,
      "time": "2185-05-08 09:36:00",
      "speaker": "Doctor",
      "text": "Tomorrow. Once the line is placed, we’ll start slowly. You’ll continue it at home through this catheter."
    },
    {
      "turn_number": 26,
      "time": "2185-05-09 11:00:00",
      "speaker": "Doctor",
      "text": "The femoral line was placed successfully. The tip is in the right spot in your vein. You can start TPN this afternoon."
    },
    {
      "turn_number": 27,
      "time": "2185-05-09 11:03:00",
      "speaker": "Patient",
      "text": "Will I feel better soon?"
    },
    {
      "turn_number": 28,
      "time": "2185-05-09 11:05:00",
      "speaker": "Doctor",
      "text": "It takes time. You’ll start to gain strength and weight over the next few weeks. We’ll monitor your labs weekly to adjust the formula."
    },
    {
      "turn_number": 29,
      "time": "2185-05-10 08:00:00",
      "speaker": "Patient",
      "text": "I’ve been on dronabinol for nausea, but it makes me so sleepy. Can we stop it?"
    },
    {
      "turn_number": 30,
      "time": "2185-05-10 08:03:00",
      "speaker": "Doctor",
      "text": "Yes, we’ll discontinue it. The ondansetron and ativan seem to be helping, and we don’t want you overly drowsy."
    },
    {
      "turn_number": 31,
      "time": "2185-05-10 08:06:00",
      "speaker": "Patient",
      "text": "Thank you. My pain is still at my usual level—about 5 out of 10. I’m taking my gabapentin and morphine as prescribed."
    },
    {
      "turn_number": 32,
      "time": "2185-05-10 08:09:00",
      "speaker": "Doctor",
      "text": "That’s expected with your condition. We’ll keep your pain regimen the same. We don’t want to increase sedation, especially with your other meds."
    },
    {
      "turn_number": 33,
      "time": "2185-05-10 14:00:00",
      "speaker": "Doctor",
      "text": "Your latest labs show your calcium is improving with supplements. Your kidney function is stable, and your hemoglobin is slowly rising."
    },
    {
      "turn_number": 34,
      "time": "2185-05-10 14:03:00",
      "speaker": "Patient",
      "text": "That’s good. I’ve been using the walker like last time. I still feel unsteady sometimes."
    },
    {
      "turn_number": 35,
      "time": "2185-05-10 14:06:00",
      "speaker": "Doctor",
      "text": "We’ll continue to encourage mobility. Physical therapy can reassess if needed, but you’re doing well walking independently."
    },
    {
      "turn_number": 36,
      "time": "2185-05-11 09:00:00",
      "speaker": "Doctor",
      "text": "We’re planning for discharge tomorrow. You’re stable, on TPN, and your nausea is better controlled."
    },
    {
      "turn_number": 37,
      "time": "2185-05-11 09:03:00",
      "speaker": "Patient",
      "text": "Home with TPN? How will I manage the line?"
    },
    {
      "turn_number": 38,
      "time": "2185-05-11 09:06:00",
      "speaker": "Doctor",
      "text": "Yes. A visiting nurse will help at first. You’ll flush the line every eight hours and do an ethanol lock daily to prevent clots and infection."
    },
    {
      "turn_number": 39,
      "time": "2185-05-11 09:09:00",
      "speaker": "Patient",
      "text": "And the TPN runs at night?"
    },
    {
      "turn_number": 40,
      "time": "2185-05-11 09:11:00",
      "speaker": "Doctor",
      "text": "Exactly. From 6 p.m. to 6 a.m. We’ll send supplies and instructions. You’ll also take your usual meds, including octreotide and gabapentin."
    },
    {
      "turn_number": 41,
      "time": "2185-05-11 09:14:00",
      "speaker": "Patient",
      "text": "What about follow-up?"
    },
    {
      "turn_number": 42,
      "time": "2185-05-11 09:16:00",
      "speaker": "Doctor",
      "text": "You’ll see your GI doctor and Dr. ___ regularly. And you need a chem-10 blood test every week—same day each week—and fax the results to Dr. ___."
    },
    {
      "turn_number": 43,
      "time": "2185-05-11 09:19:00",
      "speaker": "Patient",
      "text": "I remember from last time. I’ll make sure it’s done."
    },
    {
      "turn_number": 44,
      "time": "2185-05-11 09:21:00",
      "speaker": "Doctor",
      "text": "Good. We’ll also keep you on calcium, vitamin D, and your other supplements. Your hypothyroidism and Sjogren’s are stable—we’ll continue those meds."
    },
    {
      "turn_number": 45,
      "time": "2185-05-11 10:30:00",
      "speaker": "Patient",
      "text": "I’ve been feeling down. Not suicidal, but just… sad. Is that part of this?"
    },
    {
      "turn_number": 46,
      "time": "2185-05-11 10:33:00",
      "speaker": "Doctor",
      "text": "It’s understandable. Chronic illness takes a toll. We’re continuing your Abilify, lamotrigine, and lorazepam. Please keep talking to your psychiatrist."
    },
    {
      "turn_number": 47,
      "time": "2185-05-11 10:36:00",
      "speaker": "Patient",
      "text": "I will. Thank you for listening."
    },
    {
      "turn_number": 48,
      "time": "2185-05-11 14:00:00",
      "speaker": "Doctor",
      "text": "One more thing—we changed your stomach acid medication back to Aciphex. We used ranitidine in the hospital, but you do better on your home regimen."
    },
    {
      "turn_number": 49,
      "time": "2185-05-11 14:03:00",
      "speaker": "Patient",
      "text": "Yes, I prefer it. Less heartburn."
    },
    {
      "turn_number": 50,
      "time": "2185-05-12 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. We’re finalizing your discharge. You look well—alert, walking, and your abdomen is less tender."
    },
    {
      "turn_number": 51,
      "time": "2185-05-12 08:03:00",
      "speaker": "Patient",
      "text": "I feel more stable. Still weak, but better than when I came in."
    },
    {
      "turn_number": 52,
      "time": "2185-05-12 08:05:00",
      "speaker": "Doctor",
      "text": "You’ve made good progress. We’re discharging you home with visiting nurse support. They’ll help with TPN and line care."
    },
    {
      "turn_number": 53,
      "time": "2185-05-12 08:08:00",
      "speaker": "Patient",
      "text": "And I’ll keep taking all my meds as listed?"
    },
    {
      "turn_number": 54,
      "time": "2185-05-12 08:10:00",
      "speaker": "Doctor",
      "text": "Yes. Especially the TPN, octreotide, morphine for pain, and your psychiatric meds. Don’t stop anything without calling your doctor."
    },
    {
      "turn_number": 55,
      "time": "2185-05-12 08:13:00",
      "speaker": "Patient",
      "text": "What if I get nauseous again?"
    },
    {
      "turn_number": 56,
      "time": "2185-05-12 08:15:00",
      "speaker": "Doctor",
      "text": "Use the promethazine suppository as needed. If it’s not helping, or if you have fever, redness at the line site, or can’t run TPN, call us right away."
    },
    {
      "turn_number": 57,
      "time": "2185-05-12 08:18:00",
      "speaker": "Patient",
      "text": "I will. Thank you for everything."
    },
    {
      "turn_number": 58,
      "time": "2185-05-12 08:20:00",
      "speaker": "Doctor",
      "text": "You’re welcome. We’re glad we could help stabilize you. Take care, and keep up with your labs and follow-ups."
    },
    {
      "turn_number": 59,
      "time": "2185-05-12 08:23:00",
      "speaker": "Patient",
      "text": "I will. I just want to feel stronger again."
    },
    {
      "turn_number": 60,
      "time": "2185-05-12 08:25:00",
      "speaker": "Doctor",
      "text": "You will. It’ll take time, but you’re on the right path. We’ll see you in clinic soon."
    },
    {
      "turn_number": 61,
      "time": "2185-05-12 09:00:00",
      "speaker": "Patient",
      "text": "One last thing—should I watch for blood clots? I’ve had DVTs before."
    },
    {
      "turn_number": 62,
      "time": "2185-05-12 09:03:00",
      "speaker": "Doctor",
      "text": "Yes. Watch for leg swelling or pain, chest pain, or shortness of breath. The ethanol lock helps reduce clot risk in the line. Stay as active as you can."
    },
    {
      "turn_number": 63,
      "time": "2185-05-12 09:06:00",
      "speaker": "Patient",
      "text": "I’ll stay alert. Thank you."
    },
    {
      "turn_number": 64,
      "time": "2185-05-12 09:08:00",
      "speaker": "Doctor",
      "text": "You’re doing great. We’ll make sure your home team has all the details."
    },
    {
      "turn_number": 65,
      "time": "2185-05-12 10:00:00",
      "speaker": "Patient",
      "text": "I feel ready to go home now."
    },
    {
      "turn_number": 66,
      "time": "2185-05-12 10:02:00",
      "speaker": "Doctor",
      "text": "We’re ready to discharge you. The nurse will go over all instructions one more time before you leave."
    },
    {
      "turn_number": 67,
      "time": "2185-05-12 10:05:00",
      "speaker": "Patient",
      "text": "Okay, thank you again."
    },
    {
      "turn_number": 68,
      "time": "2185-05-12 10:07:00",
      "speaker": "Doctor",
      "text": "Take care. We’re here if you need us."
    },
    {
      "turn_number": 69,
      "time": "2185-05-12 11:00:00",
      "speaker": "Patient",
      "text": "The nurse showed me how to do the ethanol lock. I think I’ve got it."
    },
    {
      "turn_number": 70,
      "time": "2185-05-12 11:02:00",
      "speaker": "Doctor",
      "text": "That’s excellent. Consistency is key to keeping the line working and infection-free."
    },
    {
      "turn_number": 71,
      "time": "2185-05-12 11:05:00",
      "speaker": "Patient",
      "text": "I’ll be careful."
    },
    {
      "turn_number": 72,
      "time": "2185-05-12 11:07:00",
      "speaker": "Doctor",
      "text": "You’ve been very engaged in your care. That makes a big difference."
    },
    {
      "turn_number": 73,
      "time": "2185-05-12 12:00:00",
      "speaker": "Patient",
      "text": "I want to stay healthy. This has been hard, but I’m hopeful."
    },
    {
      "turn_number": 74,
      "time": "2185-05-12 12:03:00",
      "speaker": "Doctor",
      "text": "And you will. Keep up the good work. We’ll see you in follow-up."
    },
    {
      "turn_number": 75,
      "time": "2185-05-12 12:05:00",
      "speaker": "Patient",
      "text": "I’ll be there."
    },
    {
      "turn_number": 76,
      "time": "2185-05-12 13:00:00",
      "speaker": "Doctor",
      "text": "Your discharge papers are ready. You’re cleared to go home."
    },
    {
      "turn_number": 77,
      "time": "2185-05-12 13:02:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor."
    },
    {
      "turn_number": 78,
      "time": "2185-05-12 13:04:00",
      "speaker": "Doctor",
      "text": "Take care. We’re glad you’re going home stronger."
    },
    {
      "turn_number": 79,
      "time": "2185-05-12 13:06:00",
      "speaker": "Patient",
      "text": "I feel ready."
    },
    {
      "turn_number": 80,
      "time": "2185-05-12 13:08:00",
      "speaker": "Doctor",
      "text": "We’re ready too. Have a safe trip home."
    },
    {
      "turn_number": 81,
      "time": "2185-05-12 13:10:00",
      "speaker": "Patient",
      "text": "I will. Thank you for everything."
    },
    {
      "turn_number": 82,
      "time": "2185-05-12 13:12:00",
      "speaker": "Doctor",
      "text": "You’re very welcome. We’ll be in touch."
    },
    {
      "turn_number": 83,
      "time": "2185-05-12 13:15:00",
      "speaker": "Patient",
      "text": "See you soon."
    },
    {
      "turn_number": 84,
      "time": "2185-05-12 13:17:00",
      "speaker": "Doctor",
      "text": "Take care."
    },
    {
      "turn_number": 85,
      "time": "2185-05-12 13:20:00",
      "speaker": "Patient",
      "text": "Bye."
    }
  ],
  "summary": {
    "admission_start": "2185-05-01 00:39:00",
    "admission_end": "2185-05-12 14:12:00",
    "summary_paragraph": "A woman with a complex history of sclerosing mesenteritis, gastroparesis, and G-tube dependence was admitted for failure to thrive, persistent nausea, vomiting, and abdominal pain following discontinuation of home TPN due to insurance issues. She had lost 32 pounds and presented with malnutrition and hypocalcemia. During the 12-day admission, her G-tube was initially replaced to improve venting, but due to ongoing low output, it was subsequently changed to a Wills-Ogelsby tube, which improved drainage. A tunneled femoral central line was placed to reinitiate TPN after insurance approval. Nausea was managed with octreotide, ondansetron, and ativan, while dronabinol was discontinued due to sedation. Chronic pain remained stable on home medications. She was monitored for infection with negative blood and stool cultures. Upon discharge, she was stable on nightly TPN, with plans for weekly chem-10 monitoring, visiting nurse support, and follow-up with her care team.",
    "problems": [
      "Malnutrition of moderate degree",
      "Acquired hypertrophic pyloric stenosis",
      "Sclerosing mesenteritis",
      "Gastroparesis",
      "Sicca syndrome",
      "Attention to gastrostomy",
      "Hypocalcemia",
      "Adult failure to thrive",
      "Personal history of venous thrombosis and embolism",
      "Depressive disorder, not elsewhere classified",
      "Esophageal reflux",
      "Unspecified acquired hypothyroidism",
      "Asthma, unspecified type, unspecified",
      "Other chronic pain",
      "Persistent vomiting",
      "Dehydration"
    ]
  }
}
